package database

import (
    "errors"
    "gorm.io/gorm"
    "gorm.io/driver/mysql"
)
func Open(dsn string) (*gorm.DB, error) {
    if dsn == "" { return nil, errors.New("DATABASE_DSN is required") }
    return gorm.Open(mysql.Open(dsn), &gorm.Config{})
}
func Check(dsn string) error {
    db,err:=Open(dsn);if err!=nil{return err};connection,err:=db.DB();if err!=nil{return err};defer connection.Close();return connection.Ping()
}

// Migrate is an explicit application call; server startup never applies migrations.
const initialMigration = "CREATE TABLE IF NOT EXISTS schema_versions (version INTEGER PRIMARY KEY);"
func Migrate(db *gorm.DB) error { if db==nil {return errors.New("database connection is required")};return db.Exec(initialMigration).Error }

